import json
import logging
from taf.sw.neat.services.exceptions import JSONParsingError


def _parse_json_response(response):
    if hasattr(response, "json"):
        return response.json()
    if isinstance(response, dict):
        return response
    if hasattr(response, "response") and hasattr(response.response, "data"):
        json_str = response.response.data.decode("utf-8")
        return json.loads(json_str)
    if hasattr(response, "body"):
        return json.loads(response.body)
    raise AttributeError("Response object does not have expected attributes")

def get_return_data(response, raw=False):
    if not response:
        logging.error("The response is None")
        return None

    if raw:
        try:
            return _parse_json_response(response)
        except (AttributeError, UnicodeDecodeError, json.JSONDecodeError) as e:
            raise JSONParsingError(f"Failed to parse JSON response: {e}") from e

    return getattr(response, "body", response)
